using System.Collections;
using System.ComponentModel;
using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Data;
using System.Windows.Media;
namespace MRS;
// View-only controls: underlying persistent catalog/history is never deleted by Clear view.
internal sealed class MonitorOrder:IDisposable
{
 private sealed record OrderSettings(int Version,bool Newest);
 private readonly DataGrid grid;private readonly ComboBox order=new(){Width=150,ItemsSource=new[]{"Oldest on top","Newest on top"},SelectedIndex=1};private sealed record ClearedStamp(DateTimeOffset Value);private readonly System.Runtime.CompilerServices.ConditionalWeakTable<object,ClearedStamp> cleared=new();private readonly Dictionary<ICollectionView,(Predicate<object>? Base,Predicate<object> Installed)> filters=[];private Predicate<object>? originalFilter,installedFilter;private ICollectionView? view;private readonly string path;private bool dirty=true;
 internal MonitorOrder(DataGrid g,string settings,bool showClear=true){grid=g;path=settings;try{if(File.Exists(path)){using var saved=JsonDocument.Parse(File.ReadAllText(path));if(saved.RootElement.ValueKind==JsonValueKind.Object&&saved.RootElement.TryGetProperty("Version",out var version)&&version.GetInt32()==2&&saved.RootElement.TryGetProperty("Newest",out var newest))order.SelectedIndex=newest.GetBoolean()?1:0;}Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllText(path,JsonSerializer.Serialize(new OrderSettings(2,order.SelectedIndex==1)));}catch{}var host=g.Parent;if(host is ContentControl content&&ReferenceEquals(content.Content,g)){content.Content=null;var panel=new Grid();panel.Children.Add(g);content.Content=panel;host=panel;}var parent=host as Panel;if(parent==null)return;int index=parent.Children.IndexOf(g);var wrapper=new DockPanel();Grid.SetRow(wrapper,Grid.GetRow(g));Grid.SetColumn(wrapper,Grid.GetColumn(g));Grid.SetRowSpan(wrapper,Grid.GetRowSpan(g));Grid.SetColumnSpan(wrapper,Grid.GetColumnSpan(g));DockPanel.SetDock(wrapper,DockPanel.GetDock(g));parent.Children.RemoveAt(index);parent.Children.Insert(index,wrapper);var bar=new WrapPanel();DockPanel.SetDock(bar,Dock.Top);wrapper.Children.Add(bar);var clear=new Button{Content="Clear view",Padding=new Thickness(7,3,7,3),ToolTip="Hide displayed rows. Saved data stays intact; new observations appear."};if(showClear)bar.Children.Add(clear);bar.Children.Add(order);wrapper.Children.Add(g);clear.Click+=(_,_)=>Clear();order.SelectionChanged+=(_,_)=>{try{Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllText(path,JsonSerializer.Serialize(new OrderSettings(2,order.SelectedIndex==1)));}catch{}dirty=true;Refresh();};}
 internal static DateTimeOffset Time(object row){if(row==null)return DateTimeOffset.MinValue;if(row is PacketObservation p)return p.Protocol is "FT8" or "FT4" or "WSPR"?p.Weak.Utc:p.ObservedUtc;if(row is DataSummaryRow s)return s.Latest.ObservedUtc;if(row is P25DiscoveryRow d)return d.Value.LastSeen;if(row is SensorDevice sensor)return sensor.Latest.Seen;if(row is NxdnRow nx)return nx.Last.Seen;var t=row.GetType();foreach(string name in new[]{"Seen","Updated","Time","ObservedUtc","LastSeenUtc","LastSeen"}){var v=t.GetProperty(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance)?.GetValue(row)??t.GetField(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance)?.GetValue(row);if(v is DateTimeOffset stamp)return stamp;if(v is DateTime dt)return new DateTimeOffset(dt);}return DateTimeOffset.MinValue;}
 private sealed class RowComparison(bool newest):IComparer{public int Compare(object? a,object? b){int n=Time(a!).CompareTo(Time(b!));return newest?-n:n;}}
 internal bool NewestFirst=>order.SelectedIndex==1;
 internal void SetNewest(bool value){order.SelectedIndex=value?1:0;Refresh();}
 internal void Clear(){foreach(var row in grid.Items.Cast<object>().ToArray()){cleared.Remove(row);cleared.Add(row,new(Time(row)));}dirty=true;Refresh();}
 internal void Refresh(){if(!grid.IsVisible||grid.ItemsSource==null)return;var current=CollectionViewSource.GetDefaultView(grid.ItemsSource);if(current is IEditableCollectionView edit&&(edit.IsEditingItem||edit.IsAddingNew))return;if(view!=current){view=current;originalFilter=filters.TryGetValue(view,out var saved)&&ReferenceEquals(view.Filter,saved.Installed)?saved.Base:view.Filter;dirty=true;}var scroll=FindScroll(grid);double offset=scroll?.VerticalOffset??0;object? anchor=null;if(offset>1){int at=(int)offset;if(at<grid.Items.Count)anchor=grid.Items[at];}object? selected=grid.SelectedItem;try{if(view is ListCollectionView list)list.CustomSort=new RowComparison(order.SelectedIndex==1);if(dirty||!ReferenceEquals(view.Filter,installedFilter)){if(!dirty)originalFilter=view.Filter;var baseFilter=originalFilter;installedFilter=o=>(baseFilter?.Invoke(o)??true)&&(!cleared.TryGetValue(o,out var stamp)||Time(o)>stamp.Value);view.Filter=installedFilter;filters[view]=(originalFilter,installedFilter);dirty=false;}view.Refresh();if(selected!=null&&grid.Items.Contains(selected))grid.SelectedItem=selected;if(anchor!=null&&grid.Items.Contains(anchor)){int i=grid.Items.IndexOf(anchor);scroll?.ScrollToVerticalOffset(i);} }catch(InvalidOperationException){} }
 private static ScrollViewer? FindScroll(DependencyObject o){if(o is ScrollViewer s)return s;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)if(FindScroll(VisualTreeHelper.GetChild(o,i)) is {} child)return child;return null;}
 public void Dispose(){}
}
public partial class MainWindow
{
 private readonly List<MonitorOrder> monitorOrders=[];private DateTimeOffset monitorAt;
 private void InitializeMonitoringViews(){int i=0;foreach(var grid in new[]{Packets.MonitorGrid,AnalysisPackets.MonitorGrid,AviationPackets.MonitorGrid,PagingPackets.MonitorGrid,P25Packets.MonitorGrid,P25Systems.MonitorGrid,P25Activity.MonitorGrid,Dmr.MonitorGrid,nxdnGrid,trunkEventGrid,dmrTrunkEventGrid,talkgroupGrid,dmrTalkgroupGrid}.Concat(Aviation.MonitorTables).Concat(Sensors.MonitorTables))monitorOrders.Add(new(grid,Path.Combine(dataFolder,"monitor-order-"+(i++)+".json")));if(LogBox.Parent is Panel p){var clear=new Button{Content="Clear session view",HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Top};p.Children.Add(clear);clear.Click+=(_,_)=>LogBox.Clear();}}
 private void TickMonitoringViews(){if(DateTimeOffset.UtcNow<monitorAt)return;monitorAt=DateTimeOffset.UtcNow.AddMilliseconds(500);foreach(var order in monitorOrders)order.Refresh();}
}
